/* ---- batch 15: render depth sorts (iterative quicksort; its stack lives in globals) ------------- */
typedef struct { DWORD sp, lo, hi, i, j, piv, tmp; } QsGlobals;   /* lo/hi/i/j/piv are arrays indexed by the stack depth */
#define QA(base, k) G32((base) + (k) * 4)
/* sort 8-byte entries {id, float key} ascending by key in e[lo..hi]; hi also bounds the forward scan */
static void depth_sort(const QsGlobals *q, DWORD *e, int lo, int hi)
{
#define KEY(k) (*(float *)&e[(k) * 2 + 1])
#define PIV(s) GF(q->piv + (s) * 4)
	if (lo >= hi) return;
	int sp = 1;
	G32(q->sp) = 1; QA(q->lo, 1) = lo; QA(q->hi, 1) = hi;
	do {
		int bound = QA(q->hi, 1), a = QA(q->lo, sp), b = QA(q->hi, sp);
		if (a < b) {
			QA(q->i, sp) = a; QA(q->j, sp) = b + 1; GU32(q->piv + sp * 4) = e[a * 2 + 1];
			do {
				int i = ++QA(q->i, sp);
				if (i != bound)
					while (!(KEY(i) >= PIV(sp))) { QA(q->i, sp) = ++i; if (i == bound) break; }
				int j;
				do j = --QA(q->j, sp); while (KEY(j) > PIV(sp));
				i = QA(q->i, sp);
				if (i < j) {
					G32(q->tmp) = e[i * 2]; G32(q->tmp + 4) = e[i * 2 + 1];
					e[i * 2] = e[j * 2]; e[i * 2 + 1] = e[j * 2 + 1];
					int jj = QA(q->j, G32(q->sp));
					e[jj * 2] = G32(q->tmp); e[jj * 2 + 1] = G32(q->tmp + 4);
					sp = G32(q->sp);
				}
			} while (QA(q->i, sp) < QA(q->j, sp));
			int l = QA(q->lo, sp);                   /* pivot into place */
			G32(q->tmp) = e[l * 2]; G32(q->tmp + 4) = e[l * 2 + 1];
			int jj = QA(q->j, sp);
			e[l * 2] = e[jj * 2]; e[l * 2 + 1] = e[jj * 2 + 1];
			jj = QA(q->j, G32(q->sp));
			e[jj * 2] = G32(q->tmp); e[jj * 2 + 1] = G32(q->tmp + 4);
			sp = G32(q->sp) + 1; G32(q->sp) = sp;   /* push the left part */
			QA(q->lo, sp) = QA(q->lo, sp - 1); QA(q->hi, sp) = QA(q->j, sp - 1) - 1;
		} else if (a == QA(q->j, sp - 1)) {      /* left part done: do the parent's right part */
			QA(q->lo, sp) = a + 1; QA(q->hi, sp) = QA(q->hi, sp - 1);
		} else {
			if (b == QA(q->hi, sp - 1)) {           /* right part done: pop finished levels */
				do sp--; while (QA(q->hi, sp) == QA(q->hi, sp - 1));
				G32(q->sp) = sp;
			}
			QA(q->lo, sp) = QA(q->j, sp - 1) + 1; QA(q->hi, sp) = QA(q->hi, sp - 1);
		}
	} while (sp > 1);
#undef KEY
#undef PIV
}
