static void mock_finddata(BYTE *d)            /* struct _finddata_t: attrib, 3 times, size, name[260] */
{
	memset(d, 0, 0x118);
	*(DWORD *)(d + 0x10) = (DWORD)(g_mockFindPos * 1000 + 17);
	d[0x14] = 'f'; d[0x15] = 'i'; d[0x16] = 'l'; d[0x17] = 'e'; d[0x18] = (char)('0' + g_mockFindPos % 10);
}
static int __cdecl mock_findfirst(const char *spec, BYTE *d)
{
	mock_rec(0x49f694, 1, mock_hashstr(spec), 0, 0, 0);
	g_mockFindPos = 0;
	if (g_mockFindCount <= 0) return -1;
	mock_finddata(d); g_mockFindPos++;
	return 0x7e57;
}
static int __cdecl mock_findnext(int h, BYTE *d)
{
	mock_rec(0x49f75e, 1, (DWORD)h, 0, 0, 0);
	if (g_mockFindPos >= g_mockFindCount) return -1;
	mock_finddata(d); g_mockFindPos++;
	return 0;
}
