/* only the descriptor fields glWindow_setupPixelFormat sets (size, version, flags, type, colour bits, +0x12, depth,
   stencil, layer mask): the rest is whatever its stack held, which differs with the call depth */
static DWORD pfd_key(const BYTE *pfd)
{
	BYTE k[20]; memcpy(k, pfd, 10); k[10] = pfd[0x12]; k[11] = pfd[0x17]; k[12] = pfd[0x18]; memcpy(k + 13, pfd + 0x1c, 4);
	return mock_hash(k, 17);
}
