/* fake COM objects (DirectPlay, DirectSound, DirectInput): a test points the game's interface pointers at
   these. Every method call is recorded as 0xc0000000 | id << 8 | vtable slot with its first four arguments after
   this (argument harg[slot], 1-based, is replaced by the hash of hlen[slot] bytes it points at) and returns
   ret[slot]; nargs[slot] is the method's argument count after this (stdcall: the stub pops them). Out-parameters:
   outarg[slot] (1-based) receives val[slot] when the call succeeds, or fn[slot] handles the call (after it is
   recorded) and gives the result; ret0[slot] is a handler's result for a size query (no buffer) */
typedef struct FakeCom FakeCom;
struct FakeCom { void **vt; const BYTE *nargs; DWORD id; LONG ret[64], ret0[64]; DWORD val[64], val2[64]; BYTE harg[64], outarg[64];
	WORD hlen[64]; LONG (*fn[64])(FakeCom *, DWORD *); };
static DWORD g_comPop;
static DWORD __cdecl com_dispatch(DWORD *f)   /* f[0] slot, f[1] return address, f[2] this, f[3..] arguments */
{
	FakeCom *o = (FakeCom *)f[2];
	int k = (int)f[0], n = o->nargs[k];
	DWORD a[4] = {0};
	for (int i = 0; i < n && i < 4; i++) a[i] = f[3 + i];
	int h = o->harg[k];
	if (h >= 1 && h <= 4 && a[h - 1]) a[h - 1] = mock_hash((const void *)a[h - 1], o->hlen[k]);
	mock_rec(0xc0000000u | o->id << 8 | (DWORD)k, n, a[0], a[1], a[2], a[3]);
	g_comPop = 4u * (DWORD)(n + 1);
	if (o->fn[k]) return (DWORD)o->fn[k](o, f + 3);
	if (o->outarg[k] && o->ret[k] >= 0) *(DWORD *)f[2 + o->outarg[k]] = o->val[k];
	return (DWORD)o->ret[k];
}
__attribute__((naked)) static void com_common(void)
{
	__asm__ volatile("pushl %%esp\n\tcall %P0\n\taddl $4, %%esp\n\tpopl %%ecx\n\tpopl %%edx\n\t"
	                 "addl %P1, %%esp\n\tjmp *%%edx" :: "i"(com_dispatch), "i"(&g_comPop));
}
#define COMSTUB(k) __attribute__((naked)) static void com_s##k(void) { __asm__ volatile("pushl $" #k "\n\tjmp %P0" :: "i"(com_common)); }
