/* IDirectSoundBuffer Lock (11: offset, bytes, ptr1*, bytes1*, ptr2*, bytes2*, flags): the whole request in one
   part at val[11]; Unlock (19: ptr1, bytes1, ptr2, bytes2) also records the hash of the bytes written */
static LONG fc_lock(FakeCom *o, DWORD *a)
{
	*(DWORD *)a[2] = o->val[11]; *(DWORD *)a[3] = a[1];
	if (a[4]) *(DWORD *)a[4] = 0;
	if (a[5]) *(DWORD *)a[5] = 0;
	return o->ret[11];
}
static LONG fc_unlock(FakeCom *o, DWORD *a)
{
	mock_rec(0xc1000000u | o->id << 8 | 19, 2, a[0] ? mock_hash((const void *)a[0], a[1]) : 0, a[1], 0, 0);
	return o->ret[19];
}
