/* IDirectPlay4A GetPlayerName (21: id, data, size*): a size query gets val[21] bytes needed and ret0[21]; with a
   buffer of that size it is filled with bytes made from the id and gets ret[21]; from 0x18 bytes on it is a DPNAME
   (short name at +0x10, or none for odd ids; net_logMessage reads it) */
static LONG fc_getPlayerName(FakeCom *o, DWORD *a)
{
	DWORD *sz = (DWORD *)a[2], need = o->val[21];
	if (!a[1] || *sz < need) { *sz = need; return o->ret0[21]; }
	for (DWORD i = 0; i < need; i++) ((BYTE *)a[1])[i] = (BYTE)(a[0] * 7 + i);
	if (need >= 0x18) {
		DWORD *n = (DWORD *)a[1];
		n[0] = 0x10; n[1] = 0; n[2] = a[0] & 1 ? 0 : a[1] + 0x10; n[3] = 0;
		for (DWORD i = 0x10; i < need - 1; i++) ((BYTE *)a[1])[i] = (BYTE)('a' + (a[0] + i) % 26);
		((BYTE *)a[1])[need - 1] = 0;
	}
	return o->ret[21];
}
/* IDirectPlayLobby3A CreateCompoundAddress (14: elements, count, addr, size*): a size query (no buffer or one too
   small) gets val[14] bytes and ret0[14]; with a buffer, bytes made from the elements' count, ret[14].
   IDirectPlay4A GetCaps (14: caps, flags): the DPCAPS after its size filled from val[14], ret[14] */
static LONG fc_compoundAddr(FakeCom *o, DWORD *a)
{
	DWORD *sz = (DWORD *)a[3];
	if (!a[2] || *sz < o->val[14]) { *sz = o->val[14]; return o->ret0[14]; }
	for (DWORD i = 0; i < o->val[14]; i++) ((BYTE *)a[2])[i] = (BYTE)(a[1] * 13 + i);
	return o->ret[14];
}
static LONG fc_getCaps(FakeCom *o, DWORD *a)
{
	if (o->ret[14] >= 0) for (int i = 1; i < 10; i++) ((DWORD *)a[0])[i] = o->val[14] + (DWORD)i;
	return o->ret[14];
}
/* IDirectPlay4A Receive (25: from*, to*, flags, data, size*): the scripted queue g_rcv[0..g_nrcv) from position
   val2[25] (fakecom_new resets it, and a setup runs before each side): DPERR_NOMESSAGES at its end; a message
   whose ret is an error is returned as that error; with no buffer or one too small the needed size and
   DPERR_BUFFERTOOSMALL (the message stays); else the sender, the message and its size, and the next message */
typedef struct { DWORD from, len; LONG ret; BYTE data[0x80]; } FakeMsg;
static FakeMsg g_rcv[8];
static int g_nrcv;
static LONG fc_receive(FakeCom *o, DWORD *a)
{
	if ((int)o->val2[25] >= g_nrcv) return (LONG)0x887700be;
	FakeMsg *m = &g_rcv[o->val2[25]];
	if (m->ret < 0) { o->val2[25]++; return m->ret; }
	DWORD *sz = (DWORD *)a[4];
	if (!a[3] || *sz < m->len) { *sz = m->len; return (LONG)0x8877001e; }
	memcpy((void *)a[3], m->data, m->len);
	*(DWORD *)a[0] = m->from; *(DWORD *)a[1] = 0x1234; *sz = m->len;
	o->val2[25]++;
	return 0;
}
/* IDirectPlayLobby3A GetConnectionSettings (8: appID, data, size*): a size query gets 0xc0 and ret0[8]; with a
   buffer, a DPLCONNECTION (flags val[8]) whose session description and player name follow it, and ret[8] */
static LONG fc_getConnSettings(FakeCom *o, DWORD *a)
{
	DWORD *sz = (DWORD *)a[2];
	if (!a[1] || *sz < 0xc0) { *sz = 0xc0; return o->ret0[8]; }
	DWORD *c = (DWORD *)a[1];
	memset(c, 0, 0xc0);
	c[0] = 0x2c; c[1] = o->val[8]; c[2] = a[1] + 0x40; c[3] = a[1] + 0x90;
	return o->ret[8];
}
