static void mocks_install(int on)
{
	NT_TIB *tib = (NT_TIB *)NtCurrentTeb();
	/* the whole reserved stack (TEB DeallocationStack at +0xe0c), not just what is committed now: a 64 KB frame
	   (map_loadPlayInfoFrom) grows the stack below the current StackLimit */
	g_stackLo = *(DWORD *)((BYTE *)tib + 0xe0c); g_stackHi = (DWORD)tib->StackBase;
	for (unsigned i = 0; i < sizeof g_mocks / sizeof g_mocks[0]; i++) {
		BYTE *p = (BYTE *)g_mocks[i].addr;
		DWORD old;
		VirtualProtect(p, 5, PAGE_EXECUTE_READWRITE, &old);
		if (on) { memcpy(g_mocks[i].saved, p, 5); p[0] = 0xE9; *(DWORD *)(p + 1) = (DWORD)g_mocks[i].stub - ((DWORD)p + 5); }
		else memcpy(p, g_mocks[i].saved, 5);
		VirtualProtect(p, 5, old, &old);
		FlushInstructionCache(GetCurrentProcess(), p, 5);
	}
	for (unsigned i = 0; i < sizeof g_iatMocks / sizeof g_iatMocks[0]; i++) {
		DWORD *slot = (DWORD *)g_iatMocks[i].slot, old;
		VirtualProtect(slot, 4, PAGE_READWRITE, &old);
		if (on) { g_iatMocks[i].saved = *slot; *slot = (DWORD)g_iatMocks[i].stub; }
		else *slot = g_iatMocks[i].saved;
		VirtualProtect(slot, 4, old, &old);
	}
}
/* callee stubs (dispatcher tests): a setup lists the functions a dispatcher calls or jumps to with their argument
   counts (callee_stubs); each gets a jump at its entry to a stub that records the call as the callee's address
   with its arguments and returns g_stubRet (cdecl: the caller pops). They are put in before each side's run (the
   setup runs before each) and taken out after it (g_postRun), so the test checks which callee is reached with
   what, not the callees themselves (they are tested on their own). Only the real arguments are recorded: the
   stack beyond them differs between the runs (return addresses into the harness or the lifted code) */
#define MAXSTUBS 128  /* 32 until batch 196 (replay_frame stubs 42), 64 until batch 210 (game_processGameMode 87) */
static DWORD g_stubAddr[MAXSTUBS], g_stubRet, g_stubRetK[MAXSTUBS];
static int g_stubArgs[MAXSTUBS], g_nstubs, g_stubKey[MAXSTUBS];
static BYTE g_stubSaved[MAXSTUBS][5];
/* the argument count may carry CS_POP (the callee pops its arguments: stdcall / thiscall, ret N) and CS_THIS (ecx,
   thiscall's object, is recorded first); more than four arguments are recorded four at a time */
#define CS_POP 0x100
#define CS_THIS 0x200
static DWORD g_stubPop;
static DWORD __cdecl callee_dispatch(DWORD *f)   /* f[0] ecx, f[1] stub index, f[2] return address, f[3..] arguments */
{
	int k = (int)f[1], fl = g_stubArgs[k], n = fl & 0xff;
	if (fl & CS_THIS) mock_rec(g_stubAddr[k] | 0x80000000u, 0, f[0], 0, 0, 0);
	for (int i = 0; i == 0 || i < n; i += 4)
		mock_rec(g_stubAddr[k] + (DWORD)i, n, n > i ? f[3 + i] : 0, n > i + 1 ? f[4 + i] : 0, n > i + 2 ? f[5 + i] : 0, n > i + 3 ? f[6 + i] : 0);
	g_stubPop = fl & CS_POP ? 4u * (DWORD)n : 0;
	if (g_stubKey[k] != -1) return f[3] == (DWORD)g_stubKey[k];   /* callee_key: a key test answering for one key */
	return g_stubRetK[k];
}
__attribute__((naked)) static void callee_common(void)
{
	__asm__ volatile("pushl %%ecx\n\tpushl %%esp\n\tcall %P0\n\taddl $12, %%esp\n\tpopl %%edx\n\taddl %P1, %%esp\n\tjmp *%%edx"
	                 :: "i"(callee_dispatch), "i"(&g_stubPop));
}
#define CALLEESTUB(k) __attribute__((naked)) static void callee_s##k(void) { __asm__ volatile("pushl $" #k "\n\tjmp %P0" :: "i"(callee_common)); }
