static void *g_calleeStub[MAXSTUBS] = { callee_s0, callee_s1, callee_s2, callee_s3, callee_s4, callee_s5, callee_s6, callee_s7, callee_s8, callee_s9, callee_s10, callee_s11, callee_s12, callee_s13, callee_s14, callee_s15, callee_s16, callee_s17, callee_s18, callee_s19, callee_s20, callee_s21, callee_s22, callee_s23, callee_s24, callee_s25, callee_s26, callee_s27, callee_s28, callee_s29, callee_s30, callee_s31,
	callee_s32, callee_s33, callee_s34, callee_s35, callee_s36, callee_s37, callee_s38, callee_s39, callee_s40, callee_s41, callee_s42, callee_s43, callee_s44, callee_s45, callee_s46, callee_s47, callee_s48, callee_s49, callee_s50, callee_s51, callee_s52, callee_s53, callee_s54, callee_s55, callee_s56, callee_s57, callee_s58, callee_s59, callee_s60, callee_s61, callee_s62, callee_s63,
	callee_s64, callee_s65, callee_s66, callee_s67, callee_s68, callee_s69, callee_s70, callee_s71, callee_s72, callee_s73, callee_s74, callee_s75, callee_s76, callee_s77, callee_s78, callee_s79, callee_s80, callee_s81, callee_s82, callee_s83, callee_s84, callee_s85, callee_s86, callee_s87, callee_s88, callee_s89, callee_s90, callee_s91, callee_s92, callee_s93, callee_s94, callee_s95, callee_s96, callee_s97, callee_s98, callee_s99, callee_s100, callee_s101, callee_s102, callee_s103, callee_s104, callee_s105, callee_s106, callee_s107, callee_s108, callee_s109, callee_s110, callee_s111, callee_s112, callee_s113, callee_s114, callee_s115, callee_s116, callee_s117, callee_s118, callee_s119, callee_s120, callee_s121, callee_s122, callee_s123, callee_s124, callee_s125, callee_s126, callee_s127 };
static void callee_patch(int on)
{
	for (int k = 0; k < g_nstubs; k++) {
		BYTE *p = (BYTE *)g_stubAddr[k];
		DWORD old;
		VirtualProtect(p, 5, PAGE_EXECUTE_READWRITE, &old);
		if (on) { memcpy(g_stubSaved[k], p, 5); p[0] = 0xE9; *(DWORD *)(p + 1) = (DWORD)g_calleeStub[k] - ((DWORD)p + 5); }
		else memcpy(p, g_stubSaved[k], 5);
		VirtualProtect(p, 5, old, &old);
		FlushInstructionCache(GetCurrentProcess(), p, 5);
	}
	if (!on) g_nstubs = 0;
}
static void callee_unpatch(void) { callee_patch(0); }
/* list: address, argument count pairs, ended by 0; ret: what every stub returns (callee_ret / callee_key after it
   change one stub's answer) */
static void callee_stubs(const DWORD *list, DWORD ret)
{
	g_nstubs = 0;
	for (; *list && g_nstubs < MAXSTUBS; list += 2) {
		g_stubAddr[g_nstubs] = list[0]; g_stubArgs[g_nstubs] = (int)list[1];
		g_stubRetK[g_nstubs] = ret; g_stubKey[g_nstubs++] = -1;
	}
	g_stubRet = ret;
	callee_patch(1);
	g_postRun = callee_unpatch;
}
static int callee_index(DWORD addr) { for (int k = 0; k < g_nstubs; k++) if (g_stubAddr[k] == addr) return k; return -1; }
static void callee_ret(DWORD addr, DWORD ret) { int k = callee_index(addr); if (k >= 0) g_stubRetK[k] = ret; }
/* the stub at addr (a key test taking the key first) answers 1 for key, 0 for any other (-1: none pressed) */
static void callee_key(DWORD addr, int key) { int k = callee_index(addr); if (k >= 0) g_stubKey[k] = key < 0 ? -2 : key; }
