/* batch 45: virtual file content at BUF + 0x200000: random bytes, or text lines of words from the game's config
   vocabulary, numbers and separators; fopen fails sometimes */
static const char *const k_cfgWords[] = { "set_player_name", "set_player_color", "set_sound_effectvolume", "set_key", "BLUE", "YELLOW",
	"RED", "ON", "OFF", "=", ",", " ", "\t", "0", "1", "100", "-5", "999999", "TAXMAN", "arena", "Lilly", "set_video_mode", "#" };
static void vfs_content(int textp, int maxlen)
{
	char *d = BUF + 0x200000;
	int n = irnd(0, maxlen);
	if (!irnd(0, 99 - textp)) { fill(d, n); }
	else {
		int i = 0;
		while (i < n) {
			const char *w = k_cfgWords[irnd(0, 22)];
			while (*w && i < n) d[i++] = *w++;
			if (i < n && !irnd(0, 3)) d[i++] = irnd(0, 5) ? '\n' : '\r';
		}
	}
	g_vfsData = (const BYTE *)d; g_vfsSize = (DWORD)n;
	g_vfsOpenFail = !irnd(0, 7);
}
