/* axiswl.dat-like settings: lines of space/tab separated tokens where every keyword has a value after it, at least one
   token per line, short lines, some "//" comments. The original dereferences NULL on a line without tokens or with a
   keyword as its last token (strtok returns NULL), so real files never have those */
static void settings_setup(void)
{
	static const char *const keys[] = { "gamename", "secret", "password", "gametype", "fraglimit", "timelimit" };
	static const char *const vals[] = { "0", "1", "25", "-3", "99999", "TAXMAN", "arena", "x", "12abc", "" };
	char *d = BUF + 0x200000; int n = 0, lines = irnd(0, 12);
	for (int l = 0; l < lines; l++) {
		if (!irnd(0, 7)) { const char *c = "// note"; while (*c) d[n++] = *c++; }
		else for (int t = 0, toks = irnd(1, 3); t < toks; t++) {
			if (t || !irnd(0, 3)) d[n++] = irnd(0, 2) ? ' ' : '\t';
			const char *w = irnd(0, 3) ? keys[irnd(0, 5)] : vals[irnd(0, 8)];
			while (*w) d[n++] = *w++;
			d[n++] = ' ';
			w = vals[irnd(0, 8)];
			while (*w) d[n++] = *w++;
		}
		if (irnd(0, 9)) d[n++] = '\n';
	}
	g_vfsData = (const BYTE *)d; g_vfsSize = (DWORD)n;
	g_vfsOpenFail = !irnd(0, 7);
	fill_str(BUF + 0x100, 20, 33, 126);
}
