static BYTE *g_exeFile;
static DWORD g_exeSize;
static int differs(DWORD addr, const BYTE *file, DWORD size)
{
	for (DWORD i = 0; i < size; i++) {
		if (((const BYTE *)addr)[i] == file[i]) continue;
		int ok = 0;
		for (unsigned k = 0; k < sizeof g_patchOk / sizeof g_patchOk[0] && !ok; k++)
			ok = addr + i >= g_patchOk[k][0] && addr + i < g_patchOk[k][0] + g_patchOk[k][1];
		if (!ok) return 1;
	}
	return 0;
}
static int patched_in_memory(DWORD addr)
{
	int lo = 0, hi = (int)(sizeof g_fnSizes / sizeof g_fnSizes[0]) - 1, k = -1;
	while (lo <= hi) { int mid = (lo + hi) / 2; if (g_fnSizes[mid][0] == addr) { k = mid; break; } if (g_fnSizes[mid][0] < addr) lo = mid + 1; else hi = mid - 1; }
	DWORD size = k >= 0 ? g_fnSizes[k][1] : 5;          /* unknown functions: at least the entry */
	if (!g_exeFile) {
		char path[MAX_PATH]; DWORD got = 0;
		GetModuleFileNameA(NULL, path, sizeof path);
		HANDLE h = CreateFileA(path, GENERIC_READ, FILE_SHARE_READ | FILE_SHARE_WRITE, NULL, OPEN_EXISTING, 0, NULL);
		if (h == INVALID_HANDLE_VALUE) return -1;
		g_exeSize = GetFileSize(h, NULL);
		g_exeFile = VirtualAlloc(NULL, g_exeSize, MEM_COMMIT | MEM_RESERVE, PAGE_READWRITE);
		if (!g_exeFile || !ReadFile(h, g_exeFile, g_exeSize, &got, NULL) || got != g_exeSize) { CloseHandle(h); g_exeFile = NULL; return -1; }
		CloseHandle(h);
	}
	IMAGE_NT_HEADERS *nt = (IMAGE_NT_HEADERS *)(g_exeFile + ((IMAGE_DOS_HEADER *)g_exeFile)->e_lfanew);
	IMAGE_SECTION_HEADER *s = IMAGE_FIRST_SECTION(nt);
	DWORD rva = addr - nt->OptionalHeader.ImageBase;
	for (int i = 0; i < nt->FileHeader.NumberOfSections; i++, s++)
		if (rva >= s->VirtualAddress && rva + size <= s->VirtualAddress + s->SizeOfRawData) {
			DWORD off = s->PointerToRawData + (rva - s->VirtualAddress);
			return off + size <= g_exeSize && differs(addr, g_exeFile + off, size);
		}
	return -1;
}
static void hook(DWORD addr, void *fn, const char *name)
{
	DWORD old;
	unsigned char *p = (unsigned char *)addr;
	if (!passed(name)) {                       /* only bit-exact rebuilds replace the original */
		say("  KEPT ORIGINAL %08lx %s (rebuilt version did not match on every test)\n", addr, name);
		return;
	}
	{	/* rebuilt and bit-exact, but the patch DLL tells its caller by the return address of a call it makes, which a
		   lifted function cannot give: hook_glViewport widens the 2D viewport during the HUD only for a call from
		   gfx_setProjection2D3D's cave (return address 0x4a8fdd); lifted, the HUD lost its right edge */
		static const DWORD keep[] = { 0x41ef90 };
		for (unsigned i = 0; i < sizeof keep / sizeof keep[0]; i++)
			if (keep[i] == addr) { say("  KEPT ORIGINAL %08lx %s (the patch DLL checks its return address)\n", addr, name); return; }
	}
	{
		int pm = patched_in_memory(addr);
		if (pm) {
			say("  KEPT ORIGINAL %08lx %s (%s)\n", addr, name, pm > 0 ? "changed in memory by the patch DLL" : "could not compare with the exe file");
			return;
		}
	}
	{	/* RECOMP_SKIP=name,name,...: keep these on their originals (for bisecting a problem in play) */
		static char skip[4096]; static int got;
		if (!got) { got = 1; if (!GetEnvironmentVariableA("RECOMP_SKIP", skip + 1, sizeof skip - 2)) skip[1] = 0; skip[0] = ','; strcat(skip, ","); }
		char key[128];
		wsprintfA(key, ",%s,", name);
		if (skip[1] && strstr(skip, key)) { say("  KEPT ORIGINAL %08lx %s (RECOMP_SKIP)\n", addr, name); return; }
	}
	if (thread_inside(addr, 5)) {
		say("  KEPT ORIGINAL %08lx %s (a thread was stopped inside its first bytes)\n", addr, name);
		return;
	}
	VirtualProtect(p, 5, PAGE_EXECUTE_READWRITE, &old);
	p[0] = 0xE9;
	*(DWORD *)(p + 1) = (DWORD)fn - (addr + 5);
	VirtualProtect(p, 5, old, &old);
	FlushInstructionCache(GetCurrentProcess(), p, 5);
	say("  hooked %08lx %s\n", addr, name);
}

